export type BelarusCityName = (typeof BELARUS_CITIES)[number];

/** Oblast centers and the largest cities. Shown before the visitor types. */
export const BELARUS_QUICK_CITIES = [
  "Минск",
  "Гомель",
  "Могилёв",
  "Витебск",
  "Гродно",
  "Брест",
  "Бобруйск",
  "Барановичи",
  "Пинск",
  "Орша",
] as const;

export function filterBelarusCities(query: string, limit = 8): string[] {
  const q = query.trim().toLowerCase().replace(/^в\s+/, "");
  if (!q) return [...BELARUS_QUICK_CITIES];

  const starts: string[] = [];
  const includes: string[] = [];
  for (const name of BELARUS_CITIES) {
    const lower = name.toLowerCase();
    if (lower.startsWith(q)) starts.push(name);
    else if (lower.includes(q)) includes.push(name);
  }
  return [...starts, ...includes].slice(0, limit);
}
